import ast, hashlib, json
from pathlib import Path
root=Path('/workspace')
r=json.loads(root.joinpath('runtime_view.json').read_text())
p=json.loads(root.joinpath('proposal.json').read_text())
def validate(value,schema,path='"'$'"'):
    typ=schema.get('type')
    types={'object':dict,'array':list,'string':str,'boolean':bool,'number':(int,float),'integer':int}
    if typ: assert isinstance(value,types[typ]),(path,'type',typ)
    if 'const' in schema: assert value==schema['const'],(path,'const')
    if 'enum' in schema: assert value in schema['enum'],(path,'enum')
    if 'minLength' in schema: assert len(value)>=schema['minLength'],(path,'minLength')
    if 'minItems' in schema: assert len(value)>=schema['minItems'],(path,'minItems')
    if typ=='object':
        assert set(schema.get('required',[]))<=set(value),(path,'missing keys')
        if schema.get('additionalProperties') is False: assert set(value)<=set(schema.get('properties',{})),(path,'extra keys')
        for k,v in value.items():
            if k in schema.get('properties',{}):validate(v,schema['properties'][k],path+'.'+k)
    if typ=='array':
        for i,v in enumerate(value): validate(v,schema.get('items',{}),path+'['+str(i)+']')
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
allowed=set(r['context']['allowed_observation_ids'])
assert set(p['study']['evidence_refs'])<=allowed
assert p['parent_trial'] in allowed
assert 1<=len(p['variants'])<=4
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
assert any(v['role']=='candidate' for v in p['variants'])
whitelist={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'}
for v in p['variants']:
    assert set(v)=={'name','file','role','config','note'}
    assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
    assert v['role'] in ('candidate','control')
    source=root.joinpath(v['file']).read_text()
    compile(source,v['file'],'exec')
    tree=ast.parse(source)
    config=ast.literal_eval(next(n.value for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets)))
    assert config==v['config']
    assert hashlib.sha256(source.encode()).hexdigest() in v['note']
    for n in ast.walk(tree):
        if isinstance(n,ast.Import): assert all(alias.name.split('.')[0] in whitelist for alias in n.names)
        if isinstance(n,ast.ImportFrom): assert n.module.split('.')[0] in whitelist
    print('PASS source/config/hash/imports',v['file'])
for width,candidate,control in [(8,'candidate.py','frozen8_replay.py'),(16,'copy16_interact16.py','frozen16_replay.py')]:
    a,b=[ast.parse(root.joinpath(name).read_text()) for name in (candidate,control)]
    for tree in (a,b):
        tree.body=tree.body[1:]
        cls=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
        cls.body=[n for n in cls.body if not isinstance(n,ast.FunctionDef) or n.name"'!='"'_project_fields']
    assert ast.dump(a)==ast.dump(b)
    assert root.joinpath(control).read_bytes()==root.joinpath(f'history_g1_r0009_frozen{width}_interact16.py').read_bytes()
    print('PASS paired AST and exact ancestor replay',width)
assert hashlib.sha256(root.joinpath('baseline_reference.py').read_bytes()).hexdigest()=='f4b473cbacf60d72cff90f3721ad754dd617ee6065fe3fca2fc9cd4be2b25c36'
retrieved=set(r['context']['latest_knowledge_usage']['retrieved_ids'])
assert retrieved<={a['knowledge_id'] for a in p['knowledge_assessments']}
print('PASS study schema, authorized evidence, protocol, variant structure, prior knowledge review coverage and unchanged baseline')
print('NUMERICAL CHECKS NOT RUN: no torch in coding workspace; authorized host required.')
root.joinpath('runtime_view.json').unlink()
print('Removed temporary resolved-context file.')
PY"

